import { sumBy } from "../util/collections.js";
import { ValidationError } from "../util/errors.js";
import type { IdGenerator } from "../util/ids.js";
import { padLeft } from "../util/strings.js";
import { type Clock, DAY, yearOf } from "../util/time.js";
import type { Currency } from "./currency.js";
import { applyDiscounts, type Discount } from "./discount.js";
import { type Region, taxFor, taxRateFor } from "./tax.js";

export interface LineItem {
	description: string;
	quantity: number;
	/** Price of one unit, in minor units. */
	unitPrice: number;
}

export type InvoiceStatus = "draft" | "open" | "paid" | "void";

export interface Invoice {
	id: string;
	/** Human-facing number, e.g. INV-2026-0042. */
	number: string;
	userId: string;
	currency: Currency;
	region: Region;
	lines: LineItem[];
	discounts: Discount[];
	status: InvoiceStatus;
	issuedAt: number;
	paidAt: number | null;
}

export interface InvoiceTotals {
	subtotal: number;
	discount: number;
	tax: number;
	total: number;
}

export const PAYMENT_TERMS_DAYS = 30;
export const INVOICE_PREFIX = "INV";

export function lineTotal(line: LineItem): number {
	return line.quantity * line.unitPrice;
}

export function subtotal(lines: readonly LineItem[]): number {
	return sumBy(lines, lineTotal);
}

/** What an invoice comes to: subtotal, less discounts, plus tax on the discounted amount. */
export function computeTotal(invoice: Pick<Invoice, "lines" | "discounts" | "region">): InvoiceTotals {
	const sub = subtotal(invoice.lines);
	const discount = applyDiscounts(sub, invoice.discounts);
	const taxable = sub - discount;
	const tax = taxFor(taxable, taxRateFor(invoice.region));
	return { subtotal: sub, discount, tax, total: taxable + tax };
}

/**
 * The number after `previous`, stamped with the year of `issuedAt`: INV-2026-0041 -> INV-2026-0042.
 * With no previous number, numbering starts at 0001.
 */
export function nextInvoiceNumber(previous: string | undefined, issuedAt: number): string {
	const lastSequence = previous === undefined ? 0 : Number(previous.split("-")[2] ?? 0);
	return `${INVOICE_PREFIX}-${yearOf(issuedAt)}-${padLeft(lastSequence + 1, 4)}`;
}

export interface NewInvoice {
	userId: string;
	currency: Currency;
	region: Region;
	lines: LineItem[];
	discounts?: Discount[];
}

/** Builds an open invoice. Throws ValidationError if it has no lines or a line is malformed. */
export function createInvoice(input: NewInvoice, ids: IdGenerator, now: Clock, previousNumber?: string): Invoice {
	if (input.lines.length === 0) {
		throw new ValidationError("an invoice needs at least one line", ["lines"]);
	}
	for (const line of input.lines) {
		if (!Number.isInteger(line.quantity) || line.quantity <= 0 || !Number.isInteger(line.unitPrice) || line.unitPrice < 0) {
			throw new ValidationError(`bad line item: ${line.description}`, ["lines"]);
		}
	}
	const issuedAt = now();
	return {
		id: ids(),
		number: nextInvoiceNumber(previousNumber, issuedAt),
		userId: input.userId,
		currency: input.currency,
		region: input.region,
		lines: input.lines,
		discounts: input.discounts ?? [],
		status: "open",
		issuedAt,
		paidAt: null,
	};
}

export function markPaid(invoice: Invoice, now: Clock): Invoice {
	if (invoice.status !== "open") {
		throw new ValidationError(`cannot pay an invoice that is ${invoice.status}`);
	}
	return { ...invoice, status: "paid", paidAt: now() };
}

export function voidInvoice(invoice: Invoice): Invoice {
	if (invoice.status === "paid") {
		throw new ValidationError("cannot void a paid invoice");
	}
	return { ...invoice, status: "void" };
}

export function dueDate(invoice: Pick<Invoice, "issuedAt">, termsDays: number = PAYMENT_TERMS_DAYS): number {
	return invoice.issuedAt + termsDays * DAY;
}

export function isOverdue(invoice: Invoice, now: Clock, termsDays: number = PAYMENT_TERMS_DAYS): boolean {
	return invoice.status === "open" && now() > dueDate(invoice, termsDays);
}

export type Region = "US-CA" | "US-NY" | "US-OR" | "GB" | "DE" | "JP";

export interface TaxRule {
	region: Region;
	name: string;
	/** Rate in basis points: 725 means 7.25%. Integers keep the arithmetic exact. */
	rateBps: number;
}

export const TAX_RULES: Record<Region, TaxRule> = {
	"US-CA": { region: "US-CA", name: "California sales tax", rateBps: 725 },
	"US-NY": { region: "US-NY", name: "New York sales tax", rateBps: 400 },
	"US-OR": { region: "US-OR", name: "Oregon (no sales tax)", rateBps: 0 },
	GB: { region: "GB", name: "VAT", rateBps: 2000 },
	DE: { region: "DE", name: "Umsatzsteuer", rateBps: 1900 },
	JP: { region: "JP", name: "Consumption tax", rateBps: 1000 },
};

export const BASIS_POINTS = 10_000;

export function taxRateFor(region: Region): number {
	return TAX_RULES[region].rateBps;
}

/** Tax on `amount` minor units at `rateBps`, rounded half to even to a whole minor unit. */
export function taxFor(amount: number, rateBps: number): number {
	const scaled = amount * rateBps;
	const whole = Math.floor(scaled / BASIS_POINTS);
	const remainder = scaled - whole * BASIS_POINTS;
	const roundUp = remainder * 2 > BASIS_POINTS || (remainder * 2 === BASIS_POINTS && whole % 2 === 1);
	return roundUp ? whole + 1 : whole;
}

export function isTaxFree(region: Region): boolean {
	return TAX_RULES[region].rateBps === 0;
}

export interface TaxBreakdown {
	region: Region;
	name: string;
	rateBps: number;
	taxable: number;
	tax: number;
}

export function taxBreakdown(taxable: number, region: Region): TaxBreakdown {
	const rule = TAX_RULES[region];
	return { region, name: rule.name, rateBps: rule.rateBps, taxable, tax: taxFor(taxable, rule.rateBps) };
}

/** `7.25%` */
export function formatRate(rateBps: number): string {
	return `${(rateBps / 100).toFixed(2).replace(/\.?0+$/, "")}%`;
}

import * as assert from "../premise/assert.js";
import type { Tests } from "../premise/assert.js";
import { computeTotal } from "../src/billing/invoice.js";
import { taxFor } from "../src/billing/tax.js";
import { makeInvoice } from "./support.js";

export const tests: Tests = {
	"taxFor rounds exact halves to the even minor unit": () => {
		assert.eq(taxFor(250, 500), 12);
		assert.eq(taxFor(350, 500), 18);
		assert.eq(taxFor(150, 500), 8);
		assert.eq(taxFor(25, 1000), 2);
	},
	"taxFor rounds everything else to the nearest minor unit": () => {
		assert.eq(taxFor(1999, 2000), 400);
		assert.eq(taxFor(10_000, 725), 725);
		assert.eq(taxFor(251, 500), 13);
		assert.eq(taxFor(0, 2000), 0);
	},
	"computeTotal uses the same rounding": () => {
		const invoice = makeInvoice({ region: "JP", currency: "JPY", lines: [{ description: "Sticker", quantity: 1, unitPrice: 25 }] });
		assert.deepEq(computeTotal(invoice), { subtotal: 25, discount: 0, tax: 2, total: 27 });
	},
};
